import json

def build_dataset(logged, checker, keep_rationale=True):
    """Keep teacher answers that pass checks; optionally keep their reasoning."""
    rows = []
    for r in logged:                              # {"query", "answer", "rationale"}
        if not checker(r["query"], r["answer"]):
            continue                              # filter out teacher mistakes
        target = (f"{r['rationale']}\nAnswer: {r['answer']}"
                  if keep_rationale else r["answer"])
        rows.append({"messages": [{"role": "user", "content": r["query"]},
                                  {"role": "assistant", "content": target}]})
    return rows

def route(query, student, teacher, threshold=0.8):
    """Serve from the student unless it is unsure."""
    answer, confidence = student(query)
    return answer if confidence >= threshold else teacher(query)

